// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 fuzz_block_number, uint8 fuzz_extra_calls) public {
        vm.assume(fuzz_block_number > 0);
        vm.assume(fuzz_extra_calls <= 10);

        // Advance to a block just before a multiple-of-15, add a few fuzzed calls so 
        // the reference always retains >1 ether while the mutant can go below.
        uint256 base_block = (fuzz_block_number / 15) * 15;
        if (base_block == 0) base_block = 15;
        vm.roll(base_block - 1);
        vm.warp(1000);

        address alice = address(0x1000);
        address bob   = address(0x2000);
        vm.deal(alice, 100 ether);
        vm.deal(bob,   100 ether);

        // First call at block = base_block-1 (not divisible by 15) — mandatory 10 ether
        vm.prank(alice);
        c.fallback{value: 10 ether}();

        // Now at block = base_block (divisible by 15).  The next call that succeeds will
        // trigger the bulk-transfer.  We pre-fund the helper attacker for the mutant path.
        vm.roll(base_block);
        vm.warp(2000);

        // For the buggy version we need a call with 1 ether to succeed and then a
        // call at a multiple-of-15 block to sweep, potentially draining under 1 ether.
        // We let the fuzzer decide how many extra (1-ether) calls occur before the sweep.
        for (uint256 i = 0; i < fuzz_extra_calls; i++) {
            vm.prank(address(uint160(0x3000 + i)));
            vm.deal(address(uint160(0x3000 + i)), 10 ether);
            // reference: 1 ether will revert; mutant: succeeds
            try c.fallback{value: 1 ether}() {} catch {}
        }

        // Now make a 10-ether call from bob that will succeed in both versions.
        vm.prank(bob);
        c.fallback{value: 10 ether}();

        // After all above operations, the reference must have at least 1 ether because
        // each successful contribution was 10 ether and the bulk transfer at the end
        // can at most send out all previous balance (which was never below 10 ether).
        // The mutant can end up with 0 ether.
        assertTrue(address(c).balance >= 1 ether);
    }
}

