pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint48 blockNum) public {
        // Restrict amount to the admissible sending values: only 10 ether for the reference, but the fuzzer can also try 1 ether to find the bug
        vm.assume(amount == 10 ether || amount == 1 ether);
        vm.assume(blockNum > 0);
        vm.roll(blockNum);
        vm.warp(1);
        address sender = address(0x1234);
        vm.deal(sender, 100 ether);
        uint256 balanceBefore = address(c).balance;
        vm.prank(sender);
        (bool success, ) = address(c).call{value: amount}("");
        // The property: if the call succeeds, the balance must increase by exactly the sent amount,
        // because no transfer occurs unless block.number % 15 == 0, which the fuzzer may or may not trigger.
        // The reference only succeeds when amount == 10 ether, so the balance change is predictable.
        // The buggy version succeeds for both 10 ether and 1 ether, so the balance change can be smaller,
        // violating the rule that successful calls with 10 ether increase balance by 10 ether (the reference's only path).
        if (success) {
            assertEq(address(c).balance - balanceBefore, 10 ether);
        }
    }
}

