import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount1, uint256 amount2, uint48 extraTime) public {
        // admissible domain: first call must be exactly 10 ether for reference to succeed
        vm.assume(amount1 == 10 ether);
        // second call can be any amount the fuzzer tries; extraTime ensures non-zero timestamp increase
        vm.assume(extraTime >= 1);
        // fund sender
        address sender = address(0x1234);
        vm.deal(sender, amount1 + amount2);
        // first call: send exactly 10 ether
        uint256 ts1 = block.timestamp;
        vm.prank(sender);
        c.f{value: amount1}();
        uint256 past1 = c.pastBlockTime();
        // advance time
        vm.warp(ts1 + extraTime);
        // second call: with amount2, which the fuzzer will try as 1 ether to expose bug
        uint256 ts2 = block.timestamp;
        bool ok;
        vm.prank(sender);
        try c.f{value: amount2}() { ok = true; } catch { ok = false; }
        uint256 past2 = c.pastBlockTime();
        // General rule: if the second call succeeded, pastBlockTime must have advanced beyond the time of the second call.
        // Reference: amount2=10 ether succeeds and past2 > ts2. Buggy: amount2=1 ether succeeds but past2 does not advance because require(block.timestamp > pastBlockTime) uses stale pastBlockTime from first call, so past2 == past1 and past2 <= ts2 if extraTime is small.
        assertTrue(!ok || past2 > ts2);
    }
}

