// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 ts, uint8 blockMod) public {
        // ts is the block.timestamp we will use; ensure it's not zero
        vm.assume(ts > 0);
        // We'll set up c so that pastBlockTime starts equal to ts.
        // To do that, we first need a call at block.timestamp = ts-1 (or any) that sets pastBlockTime = (ts-1)+1 = ts.
        // However, the first call requires block.timestamp > pastBlockTime initially (0).
        // So we do two calls: first call at timestamp ts-1 with value 10 ether.
        // But we can't control block.timestamp globally, only via vm.warp before each transaction.
        // We'll use vm.roll to set block.number so the 15-modulus condition doesn't drain the contract.
        // Set block.number such that block.number % 15 != 0 to avoid paying out on first call.
        uint256 safeBlock = blockMod % 15 != 0 ? blockMod : blockMod + 1;
        vm.roll(safeBlock);

        address actor = address(0x1234);
        vm.deal(actor, 20 ether);

        // First call: set pastBlockTime to ts.
        uint256 initTs = ts - 1;
        vm.warp(initTs);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: 10 ether}("");
        require(ok, "first call failed");

        // Now pastBlockTime should be initTs + 1 = ts.
        // Second call: attempt with block.timestamp == ts (which equals current pastBlockTime).
        // Use same safe block number, or change if needed; ensure it doesn't trigger full payout.
        vm.roll(safeBlock);
        vm.warp(ts);
        vm.prank(actor);
        (bool ok2,) = address(c).call{value: 10 ether}("");

        // After the second call, reference would revert, leaving pastBlockTime unchanged (still ts).
        // Mutant would succeed, setting pastBlockTime to ts + 1.
        // So we check that pastBlockTime is still equal to ts (the invariant for the reference).
        // If the mutant succeeded, pastBlockTime would be ts + 1 != ts, failing the assert.
        assertTrue(c.pastBlockTime() == ts);
    }
}

