        vm.warp(1);
        vm.deal(address(this), 10 ether);
        // Ensure block.number % 15 != 0 to avoid transfer complexities
        vm.roll(1);
        c.f{value: 10 ether}();
        // After this call, pastBlockTime = block.timestamp + 1 = 2
    }

    function testFuzz_property(uint256 warpTimestamp) public {
        // warpTimestamp is the block.timestamp we will set before the next call.
        // Admissible domain: warpTimestamp must be >= 2 so that block.timestamp is at least pastBlockTime.
        // We specifically want to test when block.timestamp == pastBlockTime (i.e., 2).
        // The reference should revert, and pastBlockTime should stay 2.
        // The mutant will succeed, changing pastBlockTime to 3.
        vm.assume(warpTimestamp >= 2);
        // Keep warpTimestamp bounded to a reasonable range to avoid overflow
        vm.assume(warpTimestamp <= type(uint64).max);

        vm.warp(warpTimestamp);
        // We need block.number % 15 != 0 to avoid transfer behavior that might revert due to lack of ETH
        // But we can just set block.number to 1, which is not a multiple of 15.
        vm.roll(1);

        uint256 before = c.pastBlockTime(); // Should be 2
        vm.deal(address(this), 10 ether);
        bool ok = false;
        try c.f{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }
        uint256 afterPbt = c.pastBlockTime();

        // Rule: if block.timestamp == pastBlockTime before the call, the call must revert
        // and pastBlockTime must remain unchanged.
