        vm.assume(callCount >= 1 && callCount <= 10);

        vm.deal(address(this), 100 ether);

        for (uint8 i = 0; i < callCount; i++) {
            vm.warp(timestamp + i);
            vm.roll(blockNum + i);
            (bool ok,) = address(c).call{value: 10 ether}("");
            if (!ok) {
                vm.deal(address(this), 10 ether);
                continue;
            }
        }

        assertTrue(address(c).balance == 0);
    }
}

